import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
async function secret(name:string){const{data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data)}
function safeUrl(value:any){const u=new URL(String(value||''));if(u.protocol!=='https:'||u.hostname!=='tenant.immomio.com'||!/^\/apply\/[0-9a-f-]{8,}(?:\/.*)?$/i.test(u.pathname))throw Error('invalid_url');return u}
function baseUrl(html:string,finalUrl:string){const m=html.match(/<base[^>]+href=["']([^"']+)["']/i);return new URL(m?.[1]||finalUrl,finalUrl).href}
function collect(text:string,base:string){const out=new Set<string>();for(const re of [/<script[^>]+src=["']([^"']+)["']/gi,/<link[^>]+href=["']([^"']+)["']/gi]){let m;while((m=re.exec(text))){try{const u=new URL(m[1],base);if(u.protocol==='https:'&&u.hostname==='tenant.immomio.com')out.add(u.href)}catch{}}}return [...out]}
function around(text:string,needle:string,before=6000,after=6000,max=12){const out:string[]=[];let p=0;while(out.length<max){const i=text.indexOf(needle,p);if(i<0)break;out.push(text.slice(Math.max(0,i-before),Math.min(text.length,i+after)).replace(/\s+/g,' '));p=i+needle.length}return out}
Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method not allowed',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});const body=await req.json();const u=safeUrl(body?.url);const r=await fetch(u.href,{redirect:'follow',signal:AbortSignal.timeout(30000),headers:{'user-agent':'Mozilla/5.0','accept':'text/html'}});const html=await r.text(),base=baseUrl(html,r.url),assets=collect(html,base);const main=assets.find(x=>{try{const p=new URL(x).pathname.split('/').pop()||'';return p.startsWith('main-')&&p.endsWith('.js')}catch{return false}});if(!main)return Response.json({ok:false,error:'main_bundle_missing'});const js=await (await fetch(main,{signal:AbortSignal.timeout(30000)})).text();const head=js.slice(0,120000);return Response.json({ok:true,mainBundle:main,mainLength:js.length,contexts:{LCt:around(head,'LCt'),t5:around(head,'t5'),hierService:around(head,'_p$1'),importLines:[...head.matchAll(/import\{[^;]{0,30000}\}from\"([^\"]+\.js)\"/g)].slice(0,30).map(m=>({file:m[1],text:m[0].slice(0,30000)}))}});}catch(e:any){return Response.json({ok:false,error:String(e?.message||'inspect_failed')},{status:400})}});

