Deno.serve(async req=>{if(req.method!=='POST')return new Response('method not allowed',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});try{const response=await fetch('https://sso.immomio.com/auth/realms/immomio/protocol/openid-connect/auth/device',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded','accept':'application/json'},body:new URLSearchParams({client_id:'immomio-oidc-web',scope:'openid profile email offline_access'}),signal:AbortSignal.timeout(20000)});const body=await response.json().catch(()=>null);return Response.json({status:response.status,ok:response.ok,error:body?.error||null,errorDescription:body?.error_description||null,hasDeviceCode:!!body?.device_code,hasVerificationUri:!!body?.verification_uri});}catch(e:any){return Response.json({error:String(e?.message||'probe_failed')},{status:500})}});

import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const enc=new TextEncoder(),dec=new TextDecoder(),PROVIDER='immomio',GQL='https://gql-ps.immomio.com/tenant/graphql';
const unb64=(v:string)=>Uint8Array.from(atob(v),c=>c.charCodeAt(0));
async function secret(n:string){const{data,error}=await db.rpc('get_bot_secret',{secret_name:n});if(error||!data)throw Error('configuration_unavailable');return String(data)}
async function keyMaterial(v=1){return crypto.subtle.importKey('raw',unb64(await secret(`application_credential_key_v${v}`)),{name:'AES-GCM'},false,['decrypt'])}
async function decrypt(row:any){const v=Number(row.key_version)||1,key=await keyMaterial(v),aad=enc.encode(`${row.user_id}:${PROVIDER}:v${v}`);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(row.credential_iv),additionalData:aad},key,unb64(row.credential_ciphertext));return JSON.parse(dec.decode(plain))}
async function token(uid:string){const{data:row}=await db.from('platform_connections').select('*').eq('user_id',uid).eq('provider',PROVIDER).maybeSingle();if(!row?.credential_ciphertext)throw Error('needs_login');const c=await decrypt(row);if(!c?.access_token)throw Error('needs_login');return String(c.access_token)}
async function gql(tok:string,q:string){const r=await fetch(GQL,{method:'POST',headers:{'content-type':'application/json',accept:'application/json',origin:'https://tenant.immomio.com',referer:'https://tenant.immomio.com/','user-agent':'TraumWohnungHamburg/1.0',authorization:tok},body:JSON.stringify({query:q,variables:{input:[]}}),signal:AbortSignal.timeout(30000)});return{status:r.status,body:await r.json().catch(()=>null)}}
const q=`mutation Probe($input:[HierarchicalRootQuestionResponseInput]){hierarchicalRootQuestionResponse(input:$input){__definitelyUnknownProbeField}}`;
Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method not allowed',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});const b=await req.json(),uid=String(b.userId||'');if(!/^[0-9a-f-]{36}$/i.test(uid))throw Error('invalid_user');return Response.json({ok:true,result:await gql(await token(uid),q)});}catch(e:any){return Response.json({ok:false,error:String(e?.message||'probe_failed')},{status:400})}});
